import { useState, useMemo, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import ResponsiveImage from '../../components/ResponsiveImage';
import { useCart } from '../../context/CartContext';
import { useWishlist } from '../../context/WishlistContext';
import MenuStickySearch from '../../components/MenuStickySearch';
import ProductCard from '../../components/ProductCard';



export default function Merchandise() {
  const { addToCart } = useCart();
  const { toggleWishlist, isInWishlist } = useWishlist();
  const [priceRange, setPriceRange] = useState('all');
  const [selectedColor, setSelectedColor] = useState('all');
  const [selectedSize, setSelectedSize] = useState('all');
  const [inStockOnly, setInStockOnly] = useState(false);
  const [showFilterFAB, setShowFilterFAB] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [selectedVariant, setSelectedVariant] = useState({ size: 'M', color: 'Brown' });
  const [quantity, setQuantity] = useState(1);

  // Reset quantity when modal opens/closes
  useEffect(() => {
    if (selectedProduct) {
      setQuantity(1);
    }
  }, [selectedProduct]);
  const [searchQuery, setSearchQuery] = useState('');

  const merchandise = [
    {
      id: 'merch-001',
      name: 'TCR Premium T-Shirt',
      category: 'Apparel',
      price: 799,
      image: '/images/optimized/img-6112171a5ca5-640.webp',
      variants: {
        colors: ['Black', 'White', 'Brown'],
        sizes: ['S', 'M', 'L', 'XL']
      },
      inStock: true,
      stock: 15,
      description: 'Premium cotton t-shirt with gold TCR logo'
    },
    {
      id: 'merch-002',
      name: 'Chocolate Gift Box',
      category: 'Gifts',
      price: 1299,
      image: '/images/optimized/img-a3d8fedc7c7d-640.webp',
      variants: {},
      inStock: true,
      stock: 12,
      description: 'Assorted Belgian chocolates in premium packaging'
    },
    {
      id: 'merch-003',
      name: 'TCR Coffee Mug',
      category: 'Drinkware',
      price: 499,
      image: '/images/optimized/img-0ee7b8a9cc29-640.webp',
      variants: {
        colors: ['Brown', 'Black', 'Gold']
      },
      inStock: true,
      stock: 2,
      description: 'Ceramic mug with gold TCR branding'
    },
    {
      id: 'merch-004',
      name: 'Chocolate Making Kit',
      category: 'Kits',
      price: 1899,
      image: '/images/optimized/img-0910fd993e6b-640.webp',
      variants: {},
      inStock: true,
      stock: 5,
      description: 'DIY chocolate making kit with premium ingredients'
    },
    {
      id: 'merch-005',
      name: 'TCR Hoodie',
      category: 'Apparel',
      price: 1599,
      image: '/images/optimized/img-f94cce2dd79a-640.webp',
      variants: {
        colors: ['Black', 'Brown', 'Grey'],
        sizes: ['S', 'M', 'L', 'XL', 'XXL']
      },
      inStock: true,
      stock: 8,
      description: 'Comfortable hoodie with embroidered logo'
    },
    {
      id: 'merch-006',
      name: 'Chocolate Tasting Set',
      category: 'Gifts',
      price: 899,
      image: '/images/optimized/img-b376a74d741d-640.webp',
      variants: {},
      inStock: false,
      stock: 0,
      description: 'Curated selection of premium chocolates'
    },
    {
      id: 'merch-007',
      name: 'TCR Tote Bag',
      category: 'Accessories',
      price: 599,
      image: '/images/optimized/img-3e56acaa737b-640.webp',
      variants: {
        colors: ['Beige', 'Black', 'Brown']
      },
      inStock: true,
      stock: 20,
      description: 'Eco-friendly canvas tote with TCR branding'
    },
    {
      id: 'merch-008',
      name: 'Premium Hot Chocolate Mix',
      category: 'Food',
      price: 699,
      image: '/images/optimized/img-cb71f88519a7-640.webp',
      variants: {},
      inStock: true,
      stock: 30,
      description: 'Belgian chocolate powder for home brewing'
    }
  ];

  const colors = ['Black', 'White', 'Brown', 'Grey', 'Beige', 'Gold'];
  const sizes = ['S', 'M', 'L', 'XL', 'XXL'];

  const filteredMerchandise = useMemo(() => {
    return merchandise.filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.description.toLowerCase().includes(searchQuery.toLowerCase());
      if (!matchesSearch) return false;
      if (priceRange === 'under500' && item.price >= 500) return false;
      if (priceRange === '500-1000' && (item.price < 500 || item.price > 1000)) return false;
      if (priceRange === 'above1000' && item.price <= 1000) return false;
      if (selectedColor !== 'all' && !item.variants.colors?.includes(selectedColor)) return false;
      if (selectedSize !== 'all' && !item.variants.sizes?.includes(selectedSize)) return false;
      if (inStockOnly && !item.inStock) return false;
      return true;
    });
  }, [searchQuery, priceRange, selectedColor, selectedSize, inStockOnly]);

  const handleProductClick = (item) => {
    setSelectedProduct(item);
    setSelectedVariant({
      size: item.variants.sizes ? item.variants.sizes[0] : 'M',
      color: item.variants.colors ? item.variants.colors[0] : 'Brown'
    });
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-[#140B07] via-[#25160F] to-[#140B07]">
      {/* Search Bar Integration - Fixed at top */}
      <MenuStickySearch
        value={searchQuery}
        onChange={setSearchQuery}
        placeholder="Search for hoodies, mugs, gifts..."
      />

      {/* Main Content - offset for sticky header (navbar + search bar) */}
      <div className="pt-48 pb-20">
        <div className="max-w-[1920px] mx-auto px-8">
          {/* Header */}
          <motion.div
            className="text-center mb-8"
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
          >
            <h1 className="font-syncopate text-5xl font-bold text-[#C5A021] mb-4 tracking-wider">
              MERCHANDISE
            </h1>
            <p className="font-outfit text-[#F8F4F0]/70 text-sm">
              Exclusive TCR branded products and premium chocolate gifts
            </p>
          </motion.div>

          {/* Product Grid - Centered with Max Width */}
          <div className="w-full flex justify-center mt-8">
            <div className="flex flex-wrap gap-4 justify-start max-w-[1200px] w-full" data-product-shop>
              {filteredMerchandise.map((item, index) => (
                <ProductCard
                  key={item.id}
                  product={{
                    id: item.id,
                    name: item.name,
                    image: item.image,
                    description: item.description,
                    price: item.price,
                    rating: 4.5,
                    reviews: 120,
                    isBestSeller: false
                  }}
                  onClick={() => handleProductClick(item)}
                  index={index}
                  variant="card"
                />
              ))}
            </div>
          </div>

          {/* Empty State */}
          {filteredMerchandise.length === 0 && (
            <motion.div
              className="text-center py-20"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
            >
              <i className="ri-shopping-bag-line text-6xl text-[#C5A021]/30 mb-4"></i>
              <h3 className="font-syncopate text-2xl text-[#F8F4F0] mb-2">
                No Items Found
              </h3>
              <p className="font-outfit text-[#F8F4F0]/60">
                Try adjusting your filters
              </p>
            </motion.div>
          )}
        </div>
      </div>

      {/* Floating Action Button for Filters */}
      <motion.button
        onClick={() => setShowFilterFAB(!showFilterFAB)}
        className="fixed bottom-8 right-8 w-14 h-14 bg-gradient-to-r from-[#C5A021] to-[#D4AF37] rounded-full shadow-2xl flex items-center justify-center cursor-pointer z-[151]"
        whileHover={{ scale: 1.1, rotate: 90 }}
        whileTap={{ scale: 0.9 }}
        initial={{ scale: 0 }}
        animate={{ scale: 1 }}
        transition={{ delay: 0.5 }}
      >
        <i className={`${showFilterFAB ? 'ri-close-line' : 'ri-filter-3-line'} text-[#140B07] text-2xl`}></i>
      </motion.button>

      {/* Filter FAB Menu (No Backdrop) */}

      {showFilterFAB && (
        <motion.div
          className="fixed bottom-24 right-8 bg-[#1A110D] rounded-2xl p-4 border border-[#C5A021]/30 z-[150] w-72 shadow-2xl overflow-y-auto custom-scrollbar"
          style={{
            maxHeight: '60vh',
            overscrollBehavior: 'contain',
            WebkitOverflowScrolling: 'touch'
          }}
          initial={{ opacity: 0, y: 20, scale: 0.8 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: 20, scale: 0.8 }}
        >
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-syncopate text-xs font-bold text-[#C5A021] tracking-widest">FILTERS</h3>
            <button onClick={() => setShowFilterFAB(false)} className="text-[#F8F4F0]/40 hover:text-[#C5A021]">
              <i className="ri-close-line text-lg"></i>
            </button>
          </div>

          {/* Price Range */}
          <div className="mb-3">
            <label className="font-outfit text-xs text-[#F8F4F0]/70 mb-2 block">Price Range</label>
            <div className="space-y-1">
              {[
                { id: 'all', label: 'All Prices' },
                { id: 'under500', label: 'Under ₹500' },
                { id: '500-1000', label: '₹500 - ₹1000' },
                { id: 'above1000', label: 'Above ₹1000' }
              ].map((range) => (
                <motion.button
                  key={range.id}
                  onClick={() => setPriceRange(range.id)}
                  className={`w-full py-2 px-3 rounded-lg text-left font-outfit text-xs cursor-pointer whitespace-nowrap transition-all ${priceRange === range.id
                    ? 'bg-gradient-to-r from-[#C5A021] to-[#D4AF37] text-[#140B07] font-bold'
                    : 'bg-[#140B07]/50 text-[#F8F4F0]/70 border border-[#C5A021]/20'
                    }`}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                >
                  <i className={`${priceRange === range.id ? 'ri-radio-button-line' : 'ri-checkbox-blank-circle-line'} mr-2`}></i>
                  {range.label}
                </motion.button>
              ))}
            </div>
          </div>

          {/* Color Filter */}
          <div className="mb-3">
            <label className="font-outfit text-xs text-[#F8F4F0]/70 mb-2 block">Color</label>
            <select
              value={selectedColor}
              onChange={(e) => setSelectedColor(e.target.value)}
              className="w-full py-2 px-3 bg-[#140B07]/50 border border-[#C5A021]/20 text-[#F8F4F0] rounded-lg font-outfit text-xs cursor-pointer"
            >
              <option value="all">All Colors</option>
              {colors.map(color => (
                <option key={color} value={color}>{color}</option>
              ))}
            </select>
          </div>

          {/* Size Filter */}
          <div className="mb-3">
            <label className="font-outfit text-xs text-[#F8F4F0]/70 mb-2 block">Size</label>
            <select
              value={selectedSize}
              onChange={(e) => setSelectedSize(e.target.value)}
              className="w-full py-2 px-3 bg-[#140B07]/50 border border-[#C5A021]/20 text-[#F8F4F0] rounded-lg font-outfit text-xs cursor-pointer"
            >
              <option value="all">All Sizes</option>
              {sizes.map(size => (
                <option key={size} value={size}>{size}</option>
              ))}
            </select>
          </div>

          {/* In Stock Only */}
          <motion.button
            onClick={() => setInStockOnly(!inStockOnly)}
            className={`w-full py-2 px-3 rounded-lg font-outfit text-xs cursor-pointer whitespace-nowrap transition-all ${inStockOnly
              ? 'bg-gradient-to-r from-[#C5A021] to-[#D4AF37] text-[#140B07] font-bold'
              : 'bg-[#140B07]/50 text-[#F8F4F0]/70 border border-[#C5A021]/20'
              }`}
            whileHover={{ scale: 1.02 }}
            whileTap={{ scale: 0.98 }}
          >
            <i className={`${inStockOnly ? 'ri-checkbox-fill' : 'ri-checkbox-blank-line'} mr-2`}></i>
            In Stock Only
          </motion.button>

          {/* Clear Filters */}
          <motion.button
            onClick={() => {
              setPriceRange('all');
              setSelectedColor('all');
              setSelectedSize('all');
              setInStockOnly(false);
            }}
            className="w-full mt-3 py-2 text-[#F8F4F0]/60 font-outfit text-xs cursor-pointer hover:text-[#C5A021] transition-colors whitespace-nowrap"
            whileHover={{ scale: 1.02 }}
          >
            Clear All Filters
          </motion.button>
        </motion.div>
      )}

      {/* Quick View Modal */}
      <AnimatePresence>
        {selectedProduct && (
          <motion.div
            className="fixed inset-0 bg-black/80 backdrop-blur-sm z-[1000] flex items-center justify-center p-4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setSelectedProduct(null)}
          >
            <motion.div
              className="glass-panel-strong rounded-2xl border-2 border-gold max-w-md w-full max-h-[85vh] overflow-hidden flex flex-col"
              initial={{ scale: 0.8, y: 50 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.8, y: 50 }}
              onClick={(e) => e.stopPropagation()}
            >
              {/* Close Button */}
              <div className="absolute top-3 right-3 z-10">
                <motion.button
                  onClick={() => setSelectedProduct(null)}
                  className="w-8 h-8 rounded-full bg-cocoa-dark/80 border border-gold/20 flex items-center justify-center cursor-pointer hover:border-gold"
                  whileHover={{ scale: 1.1, rotate: 90 }}
                  whileTap={{ scale: 0.9 }}
                >
                  <i className="ri-close-line text-cream text-lg"></i>
                </motion.button>
              </div>

              {/* Scrollable Content Area */}
              <div className="flex-1 overflow-y-auto px-6 pt-6 pb-4">
                {/* Product Image */}
                <div className="relative w-full h-48 rounded-xl overflow-hidden mb-3">
                  <ResponsiveImage
                    src={selectedProduct.image}
                    alt={selectedProduct.name}
                    className="w-full h-full object-contain"
                  />
                  {!selectedProduct.inStock && (
                    <div className="absolute top-3 right-3 px-2 py-1 bg-red-500 rounded-full">
                      <span className="font-outfit text-[10px] font-bold text-white whitespace-nowrap">
                        OUT OF STOCK
                      </span>
                    </div>
                  )}
                  {selectedProduct.inStock && selectedProduct.stock && selectedProduct.stock <= 5 && (
                    <div className="absolute top-3 right-3 px-2 py-1 bg-gradient-to-r from-[#C5A021] to-red-500 rounded-full">
                      <span className="font-outfit text-[10px] font-bold text-[#0A0604] whitespace-nowrap">
                        Only {selectedProduct.stock} left
                      </span>
                    </div>
                  )}
                </div>

                {/* Product Info */}
                <h2 className="font-syncopate text-lg text-cream mb-1">{selectedProduct.name}</h2>
                <p className="font-outfit text-xs text-cream/70 mb-2">{selectedProduct.description || 'Premium merchandise item'}</p>

                <div className="flex items-center gap-2 mb-3">
                  <i className="ri-star-fill text-yellow-400 text-sm"></i>
                  <span className="font-outfit text-xs text-cream">4.5</span>
                  <span className="font-outfit text-[10px] text-cream/60">(120 reviews)</span>
                </div>

                <div className="mb-3">
                  <h3 className="font-syncopate text-[10px] text-cream mb-2">PRICE</h3>
                  <p className="text-2xl font-bold text-gold font-outfit">₹{selectedProduct.price}</p>
                  {selectedProduct.inStock && selectedProduct.stock && selectedProduct.stock <= 5 && (
                    <p className="text-xs text-red-400 mt-1 font-outfit">Only {selectedProduct.stock} left in stock</p>
                  )}
                </div>

                {/* Size Selection */}
                {selectedProduct.variants.sizes && selectedProduct.variants.sizes.length > 0 && (
                  <div className="mb-3">
                    <h3 className="font-syncopate text-[10px] text-cream mb-2">SIZE</h3>
                    <div className="flex flex-wrap gap-2">
                      {selectedProduct.variants.sizes.map((size) => (
                        <motion.button
                          key={size}
                          onClick={() => setSelectedVariant({ ...selectedVariant, size })}
                          className={`py-2 px-4 rounded-lg font-outfit cursor-pointer whitespace-nowrap transition-all ${selectedVariant.size === size
                            ? 'bg-gradient-to-r from-gold to-gold-light text-obsidian font-bold'
                            : 'bg-cocoa-dark/50 text-cream border border-gold/20 hover:border-gold/50'
                            }`}
                          whileHover={{ scale: 1.05 }}
                          whileTap={{ scale: 0.95 }}
                        >
                          <div className="text-xs font-bold">{size}</div>
                        </motion.button>
                      ))}
                    </div>
                  </div>
                )}

                {/* Color Selection */}
                {selectedProduct.variants.colors && selectedProduct.variants.colors.length > 0 && (
                  <div className="mb-3">
                    <h3 className="font-syncopate text-[10px] text-cream mb-2">COLOR</h3>
                    <div className="flex flex-wrap gap-2">
                      {selectedProduct.variants.colors.map((color) => (
                        <motion.button
                          key={color}
                          onClick={() => setSelectedVariant({ ...selectedVariant, color })}
                          className={`py-2 px-4 rounded-lg font-outfit cursor-pointer whitespace-nowrap transition-all ${selectedVariant.color === color
                            ? 'bg-gradient-to-r from-gold to-gold-light text-obsidian font-bold'
                            : 'bg-cocoa-dark/50 text-cream border border-gold/20 hover:border-gold/50'
                            }`}
                          whileHover={{ scale: 1.05 }}
                          whileTap={{ scale: 0.95 }}
                        >
                          <div className="text-xs font-bold">{color}</div>
                        </motion.button>
                      ))}
                    </div>
                  </div>
                )}

                {/* Quantity */}
                <div className="mb-3">
                  <h3 className="font-syncopate text-[10px] text-cream mb-2">QUANTITY</h3>
                  <div className="flex items-center gap-3">
                    <motion.button
                      onClick={() => setQuantity(Math.max(1, quantity - 1))}
                      className="w-8 h-8 rounded-full bg-cocoa-dark border border-gold/20 flex items-center justify-center cursor-pointer hover:border-gold"
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                    >
                      <i className="ri-subtract-line text-gold text-sm"></i>
                    </motion.button>
                    <span className="font-syncopate text-lg text-cream w-10 text-center">{quantity}</span>
                    <motion.button
                      onClick={() => setQuantity(quantity + 1)}
                      className="w-8 h-8 rounded-full bg-cocoa-dark border border-gold/20 flex items-center justify-center cursor-pointer hover:border-gold"
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                    >
                      <i className="ri-add-line text-gold text-sm"></i>
                    </motion.button>
                  </div>
                </div>
              </div>

              {/* Sticky Footer */}
              <div className="border-t border-gold/20 px-6 py-3 bg-cocoa/95 backdrop-blur-sm">
                <div className="flex items-center gap-3">
                  <motion.button
                    onClick={() => toggleWishlist(selectedProduct)}
                    className="w-10 h-10 rounded-full border border-gold/20 flex items-center justify-center cursor-pointer hover:bg-gold/10 flex-shrink-0"
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.9 }}
                  >
                    <i className={`${isInWishlist(selectedProduct.id) ? 'ri-heart-fill' : 'ri-heart-line'} text-gold text-lg`}></i>
                  </motion.button>

                  <motion.button
                    disabled={!selectedProduct.inStock}
                    onClick={() => {
                      addToCart({ ...selectedProduct, variant: selectedVariant, quantity });
                      setSelectedProduct(null);
                    }}
                    className={`flex-1 py-2.5 bg-gradient-to-r from-gold to-gold-light text-obsidian font-syncopate font-bold text-xs tracking-wider rounded-full cursor-pointer whitespace-nowrap flex items-center justify-center gap-2 ${!selectedProduct.inStock ? 'opacity-50 cursor-not-allowed' : ''}`}
                    whileHover={selectedProduct.inStock ? { scale: 1.02, boxShadow: '0 0 40px rgba(197, 160, 33, 0.6)' } : {}}
                    whileTap={selectedProduct.inStock ? { scale: 0.98 } : {}}
                  >
                    <i className="ri-shopping-cart-line"></i>
                    {selectedProduct.inStock ? 'ADD TO CART' : 'OUT OF STOCK'}
                  </motion.button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div >
  );
}
